\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
WITH s AS (SELECT s.id,s.run_id,s.result,r.outcome,r.report,l.state,l.fence,l.attempt_id,l.lease_until,l.attempt_until FROM reivro_cloud.task_submissions s LEFT JOIN reivro_cloud.runs r ON (r.project_id,r.id)=(s.project_id,s.run_id) LEFT JOIN reivro_cloud.execution_leases l ON (l.project_id,l.run_id)=(r.project_id,r.id) WHERE s.id=:'new_submission_id'::uuid), checks AS (SELECT jsonb_build_object('contract',EXISTS(SELECT FROM reivro_cloud.task_contracts WHERE id=:'new_contract_id'::uuid AND digest=:'new_digest'),'submission',CASE WHEN :'expected_events'::int=44 THEN NOT EXISTS(SELECT FROM s) ELSE EXISTS(SELECT FROM s) END,'claim',CASE WHEN :'expected_events'::int<47 THEN NOT EXISTS(SELECT FROM s WHERE run_id IS NOT NULL) ELSE EXISTS(SELECT FROM s WHERE run_id=:'run_id'::uuid AND state='running' AND fence=1 AND attempt_id=:'attempt_id'::uuid AND lease_until>clock_timestamp() AND result IS NULL AND outcome IS NULL AND report IS NULL) END,'journal',(SELECT count(*)=:'expected_events'::int AND max(seq)=:'expected_events'::int FROM reivro_cloud.events),'sequence',(SELECT last_value=:'expected_events'::int AND is_called FROM reivro_cloud.events_seq_seq)) value)
SELECT jsonb_build_object('checks',value,'all_checks_pass',NOT EXISTS(SELECT FROM jsonb_each(value)e WHERE e.value IS DISTINCT FROM 'true'::jsonb)) FROM checks;
COMMIT;
